package org.mockito.internal.creation.bytebuddy;

import java.io.*;
import java.lang.reflect.Constructor;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.exceptions.base.MockitoException;
import org.mockito.exceptions.method.InvalidUseOfMatchersException;
import org.mockito.exceptions.stubbing.MockitoException;
import org.mockito.internal.InternalMockHandler;
import org.mockito.internal.configuration.GlobalConfiguration;
import org.mockito.internal.creation.MockHandler;
import org.mockito.internal.creation.bytebuddy.ByteBuddyMockMaker;
import org.mockito.internal.creation.bytebuddy.CachingMockBytecodeGenerator;
import org.mockito.internal.creation.instance.*;
import org.mockito.internal.creation.instantiation.ClassInstantiator;
import org.mockito.internal.creation.instantiation.InstantiationException;
import org.mockito.internal.creation.mockmaker.MockMethodInterceptor;
import org.mockito.internal.settings.MockCreationSettings;
import org.mockito.internal.settings.SerializableMode;
import org.mockito.invocation.MockHandler;
import org.mockito.mock.MockCreationSettings;
import org.mockito.mock.SerializableMode;
import org.mockito.plugins.MockMaker;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;
import static org.mockito.internal.creation.bytebuddy.ByteBuddyMockMaker.asInternalMockHandler;
import static org.mockito.internal.creation.bytebuddy.ByteBuddyMockMaker.describeClass;
import static org.mockito.internal.creation.bytebuddy.ByteBuddyMockMaker.ensureMockIsAssignableToMockedType;

public class ByteBuddyMockMaker_createMock_TriageGen1Test {

    private ByteBuddyMockMaker mockMaker;
    private MockCreationSettings<Object> settings;
    private MockHandler handler;
    private CachingMockBytecodeGenerator cachingMockBytecodeGenerator;
    private ClassInstantiator classInstantiator;

    // Mock interface to implement MockAccess for successful path
    public interface MockAccess {
        void setMockitoInterceptor(MockMethodInterceptor interceptor);
    }

    public static class MockProxy implements MockAccess {
        private MockMethodInterceptor interceptor;
        @Override
        public void setMockitoInterceptor(MockMethodInterceptor interceptor) {
            this.interceptor = interceptor;
        }
    }

    @Before
    public void setUp() throws Exception {
        mockMaker = spy(new ByteBuddyMockMaker());
        settings = mock(MockCreationSettings.class);
        handler = mock(MockHandler.class);
        cachingMockBytecodeGenerator = mock(CachingMockBytecodeGenerator.class);
        classInstantiator = mock(ClassInstantiator.class);

        // Injecting dependencies via reflection since they are private fields in the real class
        setField(mockMaker, "cachingMockBytecodeGenerator", cachingMockBytecodeGenerator);
        setField(mockMaker, "classInstantiator", classInstantiator);

        // Mocking static-like behavior for the internal helper methods if possible, 
        // but since they are private/package-private, we rely on the actual logic or spy.
        // In a real Mockito environment, these are package-private.
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testCreateMock_ThrowsException_WhenSerializableModeIsAcrossClassLoaders() {
        when(settings.getSerializableMode()).thenReturn(SerializableMode.ACROSS_CLASSLOADERS);

        try {
            mockMaker.createMock(settings, handler);
            fail("Expected MockitoException");
        } catch (MockitoException e) {
            assertEquals("Serialization across classloaders not yet supported with ByteBuddyMockMaker", e.getMessage());
        }
    }

    @Test
    public void testCreateMock_Success() throws Exception {
        Class<Object> typeToMock = Object.class;
        Class<MockProxy> proxyType = MockProxy.class;

        when(settings.getSerializableMode()).thenReturn(SerializableMode.DEFAULT);
        when(settings.getTypeToMock()).thenReturn(typeToMock);
        when(cachingMockBytecodeGenerator.get(eq(typeToMock), any())).thenReturn(proxyType);
        when(classInstantiator.instantiate(proxyType)).thenReturn(new MockProxy());

        // We need to mock ensureMockIsAssignableToMockedType. 
        // Since it's a package-private method in the same package, we verify the flow.
        // For the sake of this unit test, we assume the spy handles the call or we rely on the fact 
        // that MockProxy is assignable to Object.

        Object result = mockMaker.createMock(settings, handler);

        assertNotNull(result);
        assertTrue(result instanceof MockProxy);
    }

    @Test
    public void testCreateMock_ThrowsException_WhenClassCastExceptionOccurs() throws Exception {
        Class<Object> typeToMock = Object.class;
        Class<String> wrongProxyType = String.class;

        when(settings.getSerializableMode()).thenReturn(SerializableMode.DEFAULT);
        when(settings.getTypeToMock()).thenReturn(typeToMock);
        when(cachingMockBytecodeGenerator.get(eq(typeToMock), any())).thenReturn(wrongProxyType);
        // Return a String which does NOT implement MockAccess
        when(classInstantiator.instantiate(wrongProxyType)).thenReturn("Not a mock");

        try {
            mockMaker.createMock(settings, handler);
            fail("Expected MockitoException due to ClassCastException");
        } catch (MockitoException e) {
            assertTrue(e.getMessage().contains("ClassCastException occurred while creating the mockito mock"));
        }
    }

    @Test
    public void testCreateMock_ThrowsException_WhenInstantiationExceptionOccurs() throws Exception {
        Class<Object> typeToMock = Object.class;
        Class<MockProxy> proxyType = MockProxy.class;

        when(settings.getSerializableMode()).thenReturn(SerializableMode.DEFAULT);
        when(settings.getTypeToMock()).thenReturn(typeToMock);
        when(cachingMockBytecodeGenerator.get(eq(typeToMock), any())).thenReturn(proxyType);
        when(classInstantiator.instantiate(proxyType)).thenThrow(new InstantiationException("Failed"));

        try {
            mockMaker.createMock(settings, handler);
            fail("Expected MockitoException due to InstantiationException");
        } catch (MockitoException e) {
            assertTrue(e.getMessage().contains("Unable to create mock instance of type"));
        }
    }
}
